export const dynamic = "force-dynamic";

/**
 * Pick the port forward that actually serves a game server's own port, not
 * just the first one on the record — a customer can add extra forwards
 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
 * mistaken for the game's real connect port. Falls back to the first forward
 * if none matches, so a server whose family isn't in GAME_PORT (or has no
 * exact-matching forward yet) still shows *something* rather than nothing.
 * Single shared helper so the provisioning-overlay connect string, the header
 * connect string, and the custom-domain DNS instructions can never drift from
 * each other the way three independent inline copies previously could.
 *
 * Keys on `joinPortFor`, NOT `GAME_PORT`. `GAME_PORT` is the health-CHECK map
 * and for eight families (rust, ark, projectzomboid, factorio, arkasa, soulmask,
 * squad, kf2) it deliberately names an RCON/query/admin port instead of the join
 * port — see its comment in lib/games.ts. Reading it here meant a Rust customer
 * was shown their RCON port, 28016, as the address to give their players. Found
 * live 2026-09-06 on a real fresh provision. The RCON forward still exists (the
 * provisioning health check runs through it), so this must select the join port
 * explicitly rather than rely on there being only one game forward.
 */
function gameForwardFor(server: {
  portForwards: { guestPort: number; publicPort: number }[];
  osTemplate: { family?: string | null };
  gamePlan?: { gameFamily?: string | null } | null;
}): { guestPort: number; publicPort: number } | undefined {
  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
  const joinPort = family && GAME_PORT[family] ? joinPortFor(family).port : undefined;
  const checkPort = family ? GAME_PORT[family]?.port : undefined;
  return (
    server.portForwards.find((f) => f.guestPort === joinPort) ??
    // The join forward can be legitimately absent on a server provisioned before
    // it was ever allocated — fall back to the check port rather than showing
    // nothing, same spirit as the final fallback below.
    server.portForwards.find((f) => f.guestPort === checkPort) ??
    server.portForwards[0]
  );
}

function fmtUptime(seconds: number): string {
  if (!seconds || seconds <= 0) return "—";
  const d = Math.floor(seconds / 86400);
  const h = Math.floor((seconds % 86400) / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
}

type LiveStats = {
  cpu?: number;
  mem?: number;
  maxmem?: number;
  uptime?: number;
  netin?: number;
  netout?: number;
} | null;

export default async function ServerPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; purchase?: string }>;
}) {
  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id },
    include: {
      plan: true,
      osTemplate: true,
      project: true,
      portForwards: { orderBy: { publicPort: "asc" } },
      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
      dedicatedIp: true,
      node: true,
      // Needed to price a renewal correctly: a game server bills its game plan's
      // flat price, not the base VPS plan's term price.
      gamePlan: true,
    },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();

