// Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
// display value through the decrypt fallback (legacy plaintext rows still work).
const rootPassword = serverRootPassword(server);

const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct, ipMonthlyCentsLive] =
  await Promise.all([
    db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({
      where: { active: true, category: "PLAIN_OS" },
      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
    }),
    extraDiskPerGbCents(),
    backupPlusMonthlyCents(),
    // Live annual discount — feeds the "Renew now" quote below AND the resize
    // pickers, so an annual server's renewal/upgrade/downgrade all price against the
    // same rate it was sold at.
    annualDiscountPct(),
    // Fetched unconditionally now (not just `server.dedicatedIp ? … : 0`): the
    // "Add dedicated IP" card needs the live price to show a customer who does
    // NOT yet have one, same as extraDiskPriceCents above is fetched regardless
    // of whether this server currently holds any extra disk.
    dedicatedIpMonthlyCents(),
  ]);

// VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
const owner =
  server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
const renewTaxCtx = await taxContextForUser(owner);

// What "Renew now" will actually charge, priced through the SAME function the
// action charges through, so the button cannot quote one figure and take
// another. See lib/renewal-quote.ts for the incident.
const renewQuote = renewalQuote(
  {
    termMonths: server.termMonths,
    extraDiskGB: server.extraDiskGB,
    plan: { name: server.plan.name, priceCents: server.plan.priceCents },
    // A game server is sold at its game plan's flat price, NOT the base VPS
    // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
    // a $4.99 product.
    gamePlan: server.gamePlan
      ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
      : null,
    dedicatedIp: server.dedicatedIp,
    backupTier: server.backupTier,
  },
  {
    ipMonthlyCents: server.dedicatedIp ? ipMonthlyCentsLive : 0,
    extraDiskPerGbCents: extraDiskPriceCents,
    backupPlusCents,
    annualDiscountPct: annualPct,
    // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
    // now quote are tax-inclusive, matching what renewNow charges.
    taxRatePercent: renewTaxCtx.ratePercent,
  },
);

// The server's REAL disk: plan allowance + any separately-purchased extra disk.
// Every disk figure on this page uses this, never `plan.diskGB` on its own.
//
// FIXED 2026-09-09: for a game server, "plan allowance" means the GAME
// plan's disk, not the base VPS plan's — worker/index.ts's `provision()`
// has used `server.gamePlan?.diskGB ?? server.plan.diskGB` since the
// 2026-09-06 over-provisioning fix (a game plan is never LARGER than its
// base VPS tier), but this page's own `totalDiskGB` was never updated to
// match, so a game server's dashboard silently showed the bigger base-VPS
// number here even though the VM itself was correctly provisioned at the
// smaller, advertised size. Found live on a real Valheim server (30GB
// advertised + actually provisioned, dashboard showed 50GB) — the exact
// "advertised != displayed" trust problem the original fix existed to
// prevent, just relocated to the display layer instead of provisioning.
const baseDiskGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
const totalDiskGB = effectiveDiskGB(baseDiskGB, server.extraDiskGB);

const publicIp = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
const busy =
  transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
const steady = ["RUNNING", "STOPPED"].includes(server.status);

let live: LiveStats = null;
let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
let backups: { volid: string; ctime?: number; size?: number }[] = [];
let pveUnavailable = false;

if (server.vmid && steady) {
  // Read through THIS server's own node's Proxmox client — vmids can
  // collide across nodes, so the bare vmStatus/listSnapshots/listBackups
  // (always the primary node) would show a customer someone else's VM's
  // stats the moment their server lives on a different node. Falls back to
  // the primary-node singleton only for the legacy case of a server with
  // no `node` relation at all (pre-multi-node rows).
  const conn = server.node ? pveForNode(server.node) : null;
  // listBackupsOn's own default storage id ("backup") is the PRIMARY's own
  // vzdump storage name — a non-primary node's is its own `storageHdd`
  // (worker/index.ts and lib/actions-server-ops.ts already resolve it this
  // way). Omitting this here made every node-2+ server's Backups tab fail
  // with "hypervisor is briefly unavailable" — confirmed live 2026-09-08,
  // Proxmox 500s on GET /nodes/<node>/storage/backup/content because that
  // storage id doesn't exist there (node-2's is "vmdata-hdd").
  const backupStorage = server.node
    ? server.node.isPrimary
      ? "backup"
      : (server.node.storageHdd ?? "backup")
    : "backup";
  const results = await Promise.allSettled([
    conn ? conn.vmStatus(server.vmid) : vmStatus(server.vmid),
    conn ? listSnapshotsOn(conn, server.vmid) : listSnapshots(server.vmid),
    conn ? listBackupsOn(conn, server.vmid, backupStorage) : listBackups(server.vmid),
  ]);
  if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
  if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
  if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
  pveUnavailable = results.some((r) => r.status === "rejected");
}

// Dedicated-IP servers connect straight to their own public IP on port 22; NAT
// servers use the platform public IP + the forwarded SSH port. (A dedicated
// server has sshPort=null, which previously fell through to "provisioning…".)
const sshCommand = server.dedicatedIp
  ? `ssh root@${server.dedicatedIp.address}`
  : server.sshPort
    ? `ssh root@${publicIp} -p ${server.sshPort}`
    : null;

// Single-item terminal list for this server — connect string computed the
// same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
const terminalServers = [
  {
    id: server.id,
    hostname: server.hostname,
    connect: server.dedicatedIp
      ? `ssh root@${server.dedicatedIp.address}`
      : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
  },
];

// SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
// port 22; NAT servers use the platform public IP + the forwarded SSH port.
const dedicated = !!server.dedicatedIp;
const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
const sftpPort = dedicated ? 22 : server.sshPort;
const isGameServer = GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);

// Post-payment "setting up / it's live" interstitial. Connect string mirrors
// the game-branch's own `connect` computation below via the shared
// gameForwardFor() helper, so the two can never drift from each other.
const overlayForward = isGameServer ? gameForwardFor(server) : undefined;
const overlayConnect = isGameServer
  ? server.dedicatedIp
    ? `${server.dedicatedIp.address}${overlayForward ? `:${overlayForward.guestPort}` : ""}`
    : overlayForward
      ? `${publicIp}:${overlayForward.publicPort}`
      : publicIp || null
  : sshCommand;
// Real (not cosmetic) step label when the worker has recorded one for this
// server's CURRENT provisioning run — see lib/provisioning-step.ts. Null while
// transitional but no checkpoint reached yet (or in SANDBOX, which completes
// before any step is ever written) simply falls back to the overlay's existing
// cosmetic cycling text.
const liveStep = transitional ? await serverProvisioningStep(server.id) : null;
/* The Nexion provisioning screen. It replaces <ProvisioningOverlay/> for the
   three states it covers — building, live, failed — and is driven by the SAME
   real signals the old one used: `server.status` and `serverProvisioningStep`.
   The design sandbox animated this on a timer; nothing here advances unless
   the worker actually reported a step.

   This is the destination `payAndDeploy` redirects to, so it is the screen a
   customer really sees after ordering — the wizard's own step 5 is never
   reached on that path. */
const overlay = transitional || purchase === "1" || server.status === "ERROR" ? (
  <Provisioning
    phase={server.status === "ERROR" ? "error" : transitional ? "working" : "ready"}
    liveStep={liveStep}
    /* Sandbox only: no hypervisor here means the worker never reports a step,
       so the stage list would sit inert forever and the screen could not be
       judged. Never true in production — NXEON_SANDBOX is not set there. */
    simulate={process.env.NXEON_SANDBOX === "1" && !liveStep}
    hostname={server.hostname}
    planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
    osName={server.osTemplate.name}
    connectAddress={overlayConnect}
    error={server.provisionError}
    dashboardHref={`/dashboard/servers/${server.id}`}
    service={isGameServer ? "game" : "vps"}
    /* Real figures off the plan the customer is actually being given — the
       same `totalDiskGB` the rest of the page uses, so the provisioning
       screen and the server page cannot quote different disk. */
    specs={[
      { icon: "cpu", text: `${server.plan.cpuCores} vCPU` },
      { icon: "ram", text: `${server.plan.ramMB / 1024} GB RAM` },
      { icon: "database", text: `${totalDiskGB} GB NVMe` },
    ]}
    slots={isGameServer ? server.gamePlan?.slots ?? null : null}
    /* `Node.region` is a slug ("sgp1"); REGION_LABELS is the one place that
       turns it into the name a customer recognises. */
    regionName={server.node ? REGION_LABELS[server.node.region] ?? null : null}
  />
) : null;

/* While the server is being built — or immediately after paying — this screen
   is the WHOLE page. The tabs, the access panel and the SSH box below are
   controls for a machine that does not exist yet: showing "provisioning…"
   inside a Root password field invites the customer to keep checking a box
   that cannot fill. They come back the moment the server is real, via the
   Continue button. */
if (overlay) {
  return (
    <div className="min-h-[70vh]">
      {transitional && <AutoRefresh />}
      {overlay}
    </div>
  );
}

const legacyOverlay = (
  <ProvisioningOverlay
    serverId={server.id}
    status={server.status}
    transitional={transitional}
    justPaid={purchase === "1"}
    provisionError={server.provisionError}
    productLabel={isGameServer ? "game server" : "server"}
    hostname={server.hostname}
    connectAddress={overlayConnect}
    planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
    osName={server.osTemplate.name}
    rootPassword={rootPassword}
    liveStep={liveStep}
    dashboardHref={`/dashboard/servers/${server.id}`}
  />
);

// Per-game customization (only for game servers with a customization schema).
const gameFamily = familyFor(server);
const gameSchema = schemaFor(gameFamily);
const gameVariant =
  gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
    ? server.gameVariant
    : gameSchema?.defaultVariant ?? "";
const gameValidated = gameFamily
  ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
  : null;
const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};

/* ---------- Tab: Overview ---------- */
const overview = (
  // `grid-cols-1` is load-bearing below `md`. With no base template the browser
  // creates an IMPLICIT `auto` track, sized to min-content and unclampable: at
  // 390px the rehearsal measured it at 530px — the `ssh root@… -p …` <code> and
  // the SFTP/SSH credentials are unbreakable strings — scrolling the whole page
  // 156px sideways. `grid-cols-1` compiles to `repeat(1, minmax(0, 1fr))`, the
  // same minmax `md:grid-cols-2` already applies, which is why desktop was fine.
  <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
    {/* Wired straight from the live stats already fetched above for this same
        render (`live.cpu`/`live.mem`/`live.maxmem`) — no new data fetching.
        There's no per-page disk sample for a VPS (DiskUsageChart below fetches
