          </p>
        )}
      </div>

      <div className="card">
        <h2 className="mb-4 font-semibold">Add firewall rule</h2>
        <AddFirewallRuleForm serverId={server.id} />
      </div>
    </div>
  );

  /* ---------- Tab: Resize ---------- */
  const resize = (
    <div className="space-y-6">
      {/* Only offered when the server doesn't already have one — a server that
          already holds a dedicated IP has nothing to add. */}
      {!dedicated && (
        <AddDedicatedIp
          serverId={server.id}
          hostname={server.hostname}
          monthlyCents={ipMonthlyCentsLive}
          expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
          isFree={server.isFree}
          walletBalanceCents={user.balanceCents}
          disabled={busy || !steady}
        />
      )}

      {/* Disk-only growth sits ABOVE the plan pickers: most customers who come
          here just need more space, and this is the cheap answer that leaves
          their CPU/RAM/price alone. One-way — see the component. */}
      <AddStorage
        serverId={server.id}
        hostname={server.hostname}
        planDiskGB={server.plan.diskGB}
        extraDiskGB={server.extraDiskGB}
        pricePerGbCents={extraDiskPriceCents}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        isFree={server.isFree}
        walletBalanceCents={user.balanceCents}
        disabled={busy || !steady}
      />

      <ResizePicker
        serverId={server.id}
        currentPlanId={server.planId}
        currentDiskGB={server.plan.diskGB}
        currentPriceCents={server.plan.priceCents}
        extraDiskGB={server.extraDiskGB}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        termMonths={server.termMonths}
        termPromoPercent={server.termPromoPercent}
        annualDiscountPct={frozenAnnualDiscountPct(server) ?? annualPct}
        isFree={server.isFree}
        walletBalanceCents={user.balanceCents}
        plans={activePlans.map((p) => ({
          id: p.id,
          name: p.name,
          cpuCores: p.cpuCores,
          ramMB: p.ramMB,
          diskGB: p.diskGB,
          bandwidthTB: p.bandwidthTB,
          priceCents: p.priceCents,
        }))}
        disabled={busy || !steady}
      />

      <ResizeDown
        serverId={server.id}
        currentPlanId={server.planId}
        currentDiskGB={server.plan.diskGB}
        currentPriceCents={server.plan.priceCents}
        termMonths={server.termMonths}
        termPromoPercent={server.termPromoPercent}
        annualDiscountPct={frozenAnnualDiscountPct(server) ?? annualPct}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        isFree={server.isFree}
        plans={activePlans.map((p) => ({
          id: p.id,
          name: p.name,
          cpuCores: p.cpuCores,
          ramMB: p.ramMB,
          diskGB: p.diskGB,
          bandwidthTB: p.bandwidthTB,
          priceCents: p.priceCents,
        }))}
        disabled={busy || !steady}
      />

      {/* Image minimum-disk checks run against the EFFECTIVE disk (totalDiskGB):
          a server that bought extra storage really does have room for a larger
          image than its plan alone would allow. */}
      <ReinstallOs
        serverId={server.id}
        currentOsTemplateId={server.osTemplateId}
        currentOsName={server.osTemplate.name}
        planRamMB={server.plan.ramMB}
        planDiskGB={totalDiskGB}
        templates={osTemplates.map((t) => ({
          id: t.id,
          name: t.name,
          family: t.family,
          version: t.version,
          minRamMB: t.minRamMB,
          minDiskGB: t.minDiskGB,
        }))}
        disabled={busy || !steady}
      />
    </div>
  );

  /* ---------- Tab: Activity ---------- */
  const planNames: Record<string, string> = Object.fromEntries(
    activePlans.map((p) => [p.id, p.name])
  );
  const activity = (
    <div className="card p-0">
      <p className="section-label px-5 pt-4">Deployment & lifecycle timeline</p>
      <ActivityTimeline jobs={server.jobs} planNames={planNames} />
    </div>
  );

  /* ---------- Tab: Console ---------- */
  const consolePanel =
    server.vmid && server.status === "RUNNING" ? (
      <Console serverId={server.id} />
    ) : (
      <div className="card py-12 text-center">
        <h2 className="font-semibold">Console unavailable</h2>
        <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
          The VNC console is available only while your server is{" "}
          <span className="font-medium text-slate-200">running</span>. Start the server to open a
          graphical session.
        </p>
      </div>
    );

  /* ---------- Premium game-server management panel ---------- */
  // For game servers, replace the generic VPS tab shell with the dedicated
  // panel (persistent vitals header + game tabs + Mod Store + Build with AI).
  if (isGameServer) {
    const gameLabel = server.osTemplate.name;
    const gameFamilyKey = server.gamePlan?.gameFamily ?? server.osTemplate.family;
    const gameForward = gameForwardFor(server);
    const connectPort = server.dedicatedIp ? gameForward?.guestPort : gameForward?.publicPort;
    const rawConnect = server.dedicatedIp
      ? `${server.dedicatedIp.address}${gameForward ? `:${gameForward.guestPort}` : ""}`
      : gameForward
        ? `${publicIp}:${gameForward.publicPort}`
        : publicIp || null;
    // A Java Minecraft subdomain (SRV-backed, see lib/game-subdomain-dns.ts)
    // needs no port shown at all — the client resolves it automatically. Every
    // other family with a subdomain (Bedrock + HOSTNAME_CONNECT_FAMILIES,
    // lib/games.ts) has NO SRV support, so the port must still be appended —
    // showing a bare hostname there would reproduce the exact "no port needed"
    // miscopy already found and fixed for Bedrock's checkout wizard.
    const gameSubdomainDomain = await gameSubdomainBase();
    const connect = server.subdomain
      ? gameFamilyKey === "minecraft"
        ? `${server.subdomain}.${gameSubdomainDomain}`
        : `${server.subdomain}.${gameSubdomainDomain}${connectPort ? `:${connectPort}` : ""}`
      : rawConnect;

    // Effective public IP + port for the custom-domain DNS instructions.
    const effectiveIp = server.dedicatedIp?.address ?? publicIp;
    const effectivePort = server.dedicatedIp
      ? (gameForward?.guestPort ?? 25565)
      : (gameForward?.publicPort ?? 25565);

    // Soonest enabled auto-restart, for the "Next restart" field.
    const nextSchedule = await db.gameSchedule.findFirst({
      where: { serverId: server.id, enabled: true, nextRunAt: { not: null } },
      orderBy: { nextRunAt: "asc" },
    });

    const latestDisk = await db.serverDiskSample.findFirst({
      where: { serverId: server.id },
      orderBy: { ts: "desc" },
      select: { usedBytes: true },
    }).catch(() => null);
    const diskUsedGB = latestDisk ? Number(latestDisk.usedBytes) / (1024 ** 3) : 0;

    // `Server.status` is the VM's own power state; GAME_POWER start/stop/
    // restart (worker/game-control.ts's gamePower) only ever touches the game
    // SERVICE inside a running VM and never changes it — those are genuinely
    // different things. Without this, a customer who stopped just their game
    // service (VM still RUNNING) kept seeing "Online" no matter what they did
    // — found live 2026-09-09 via a real customer confused why the status
    // never changed after repeated stop/start attempts. `_serviceState`
    // (gameConfig, written by gamePower) is the real systemd state; only
    // override the VM-derived display when it's known and explicitly not
    // "active" — an unknown/missing marker (every server provisioned before
    // this fix, or any non-game-service family) falls back to VM status
    // exactly as before.
    const serviceState = (server.gameConfig as Record<string, unknown> | null)?._serviceState;
    const serviceStopped = server.status === "RUNNING" && typeof serviceState === "string" && serviceState !== "active";
    const displayStatus = serviceStopped ? "STOPPED" : server.status;

    const header: GameHeaderData = {
      name: server.label || server.name,
      gameLabel,
      status: displayStatus,
      running: displayStatus === "RUNNING",
      connect,
      serverIdShort: `#${server.id.slice(0, 10)}`,
      node: server.node?.name ?? null,
      location: null,
      players: { online: 0, max: server.gamePlan?.slots ?? null },
      cpuPct: (live?.cpu ?? 0) * 100,
      // Fallback only (live.maxmem is the real, authoritative value and is
      // used whenever available) — but when it's missing, a game server's
      // real ram ceiling is its game plan's, not the (larger) base VPS plan.
      mem: { usedBytes: live?.mem ?? 0, maxBytes: live?.maxmem ?? (server.gamePlan?.ramMB ?? server.plan.ramMB) * 1024 * 1024 },
      disk: { usedGB: Math.round(diskUsedGB * 10) / 10, maxGB: totalDiskGB },
      net: { inMbps: null, outMbps: null },
      uptimeLabel: fmtUptime(live?.uptime ?? 0),
      createdLabel: server.createdAt.toISOString().slice(0, 10),
      nextRestartLabel: nextSchedule?.nextRunAt
        ? `${nextSchedule.nextRunAt.toISOString().slice(0, 16).replace("T", " ")} UTC`
        : null,
      canControl: steady && !busy,
      customDomain: server.customDomain ?? null,
      customDomainVerified: server.customDomainVerified,
    };

    // Other ACTIVE tiers in the same game family, for the informational
    // "Resize & storage" card below — cheapest first. See GameTierInfo's own
    // header comment for why this is informational rather than a self-serve
    // resize control.
    const gameTierSiblings =
      server.gamePlanId && server.gamePlan
        ? await db.gamePlan.findMany({
            where: { gameFamily: gameFamilyKey, active: true, id: { not: server.gamePlanId } },
            orderBy: { priceCents: "asc" },
            select: {
              id: true,
              name: true,
              ramMB: true,
              cpuCores: true,
              diskGB: true,
              slots: true,
              priceCents: true,
              termMonths: true,
            },
          })
        : [];

    const gameSettingsPanel = (
      <div className="space-y-6">
        {/* Wired from the same `header` values GameServerPanel's vitals strip
            already renders (`header.cpuPct`, `header.mem`, `header.disk`) — no
            new data fetching. */}
        <ResourceLimitAlert
          cpuPct={header.cpuPct}
          memPct={header.mem.maxBytes ? (header.mem.usedBytes / header.mem.maxBytes) * 100 : null}
          diskPct={header.disk.maxGB ? (header.disk.usedGB / header.disk.maxGB) * 100 : null}
          upgradeHref={`/dashboard/servers/${server.id}?tab=settings`}
        />

        <div className="card">
          <h2 className="mb-3 font-semibold">Server name</h2>
          <ServerRename serverId={server.id} label={server.label} fallback={server.name} />
        </div>

        {server.gamePlanId && server.gamePlan && (
          <GameTierInfo
            hostname={server.hostname}
            current={{
              id: server.gamePlan.id,
              name: server.gamePlan.name,
              ramMB: server.gamePlan.ramMB,
              cpuCores: server.gamePlan.cpuCores,
              diskGB: server.gamePlan.diskGB,
              slots: server.gamePlan.slots,
              priceCents: server.gamePlan.priceCents,
              termMonths: server.gamePlan.termMonths,
            }}
            otherTiers={gameTierSiblings}
            effectiveDiskGB={totalDiskGB}
            extraDiskGB={server.extraDiskGB}
          />
        )}

        {/* Dedicated IP is a real (billed) add-on for game servers too — unlike
            plan/disk changes, it isn't part of the flat-bundle price, so it's
            fully self-service here. Only offered when the server doesn't
            already have one. */}
        {!dedicated && (
          <AddDedicatedIp
            serverId={server.id}
            hostname={server.hostname}
            monthlyCents={ipMonthlyCentsLive}
            expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
            isFree={server.isFree}
            walletBalanceCents={user.balanceCents}
            disabled={busy || !steady}
          />
        )}

        {server.gamePlanId && gameSchema && (
          <GameSettings
            serverId={server.id}
            schema={gameSchema}
            variant={gameVariant}
            values={gameValues}
            disabled={busy || !steady}
          />
        )}

        <GameAutoUpdate
          serverId={server.id}
          gameName={server.osTemplate.name}
          autoUpdate={server.autoUpdate}
          canUpdate={server.status === "RUNNING"}
          busy={busy}
        />

        <GameSchedules serverId={server.id} />

        <div className="card">
          <h3 className="font-semibold">Network</h3>
          <p className="mt-1 text-sm text-slate-400">Your server connects on:</p>
          <div className="mt-2 inline-flex items-center gap-2 rounded-lg border border-white/10 bg-navy-950/70 px-3 py-1.5 font-mono text-xs text-slate-200">
            {connect ?? "provisioning…"}
          </div>
          {server.customDomainVerified && server.customDomain && (
            <div className="mt-2 inline-flex items-center gap-2 rounded-lg border border-emerald-500/20 bg-navy-950/70 px-3 py-1.5 font-mono text-xs text-emerald-300">
              {server.customDomain}
              <span className="rounded-full border border-emerald-500/25 bg-emerald-500/[0.08] px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-emerald-400">
                custom
              </span>
            </div>
          )}
          {server.subdomain && rawConnect && rawConnect !== connect && (
            <p className="mt-2 text-xs text-slate-500">
              Fallback (raw address): <span className="font-mono">{rawConnect}</span>
            </p>
          )}
          <p className="mt-3 text-xs text-slate-500">Port forwarding and firewall rules for this VM are managed in the platform Networking controls.</p>
          {(gameFamilyKey === "minecraft" || gameFamilyKey === "bedrock" || HOSTNAME_CONNECT_FAMILIES.has(gameFamilyKey as GameFamily)) && (
            <>
              <div className="divider" />
              <h4 className="text-sm font-semibold text-slate-200">Connect address</h4>
              <p className="mt-1 text-xs text-slate-500">
                {gameFamilyKey === "minecraft"
                  ? server.subdomain
                    ? "Change the subdomain players use to connect — your world stays intact."
                    : "Pick a subdomain so players can connect with a name instead of a raw IP and port."
                  : server.subdomain
                    ? "Change the subdomain players use — they'll still need to enter the port alongside it (no game here supports a port-free connect except Java Minecraft)."
                    : "Pick a subdomain so players connect with a name instead of a raw IP — they'll still need the port too."}
              </p>
              <ChangeGameSubdomain serverId={server.id} subdomain={server.subdomain} domain={gameSubdomainDomain} />
            </>
          )}
        </div>

        {gameFamilyKey === "minecraft" && effectiveIp && (
          <GameCustomDomain
            serverId={server.id}
            serverIp={effectiveIp}
            serverPort={effectivePort}
            currentDomain={server.customDomain ?? null}
            verified={server.customDomainVerified}
          />
        )}

        <div className="card">
          <h3 className="font-semibold">Access</h3>
          <p className="mt-1 text-sm text-slate-400">SSH/SFTP into the VM hosting this game server — for plugin uploads, config edits, or anything outside the Files tab.</p>
          <dl className="mt-3 space-y-3 text-sm">
            <div>
              <dt className="text-slate-400">SSH command</dt>
              <dd className="mt-1 flex items-center gap-2">
                <code className="min-w-0 flex-1 overflow-x-auto whitespace-nowrap rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
                  {sshCommand ?? "provisioning…"}
                </code>
                {sshCommand && <CopyText text={sshCommand} />}
              </dd>
            </div>
            <div className="flex items-center justify-between">
              <dt className="text-slate-400">Root password</dt>
              <dd>
                {rootPassword ? <RevealPassword password={rootPassword} /> : <span className="text-slate-500">—</span>}
              </dd>
            </div>
          </dl>
          <div className="divider" />
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="text-xs text-slate-500">Lost access or rotating credentials? Generate a fresh root password.</p>
            <ResetPasswordButton serverId={server.id} disabled={busy || !steady} />
          </div>
        </div>

        <SftpAccess host={sftpHost} port={sftpPort} password={rootPassword} dedicated={dedicated} />

        <GamePublicListing serverId={server.id} connectAddress={connect} />
      </div>
    );

    return (
      <div>
        {overlay}
        {busy && <AutoRefresh />}

        {server.status === "SUSPENDED" && (
          <div className="card mb-6 border-red-500/30 text-sm text-red-300">
            This server has been suspended{server.suspendedNote ? `: ${server.suspendedNote}` : "."}{" "}
            Contact support if you believe this is a mistake.
          </div>
        )}
        {server.status === "ERROR" && <ProvisionErrorBanner serverId={server.id} reason={server.provisionError} />}
        {transitional && (
          <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
            {server.status === "DELETING"
              ? "Your server is being deleted…"
              : "Your server is being set up — this usually takes under two minutes. The page refreshes automatically."}
          </div>
        )}

        <div className="mb-4">
          <a href="/dashboard/servers" className="text-xs text-slate-500 hover:text-slate-300">
            ← Game Servers
          </a>
        </div>

        <GameServerPanel
          serverId={server.id}
          gameFamily={gameFamilyKey}
          header={header}
          filesPanel={filesPanel}
          backupsPanel={backupsTab}
          settingsPanel={gameSettingsPanel}
          activityPanel={activity}
          initialTab={tab}
        />
      </div>
    );
  }

  return (
    <div>
      {overlay}
      {busy && <AutoRefresh />}

      <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
        <div>
          <div className="flex flex-wrap items-center gap-3">
            <h1 className="page-title">{server.label || server.name}</h1>
            <StatusDot status={server.status} />
            <ServerRename serverId={server.id} label={server.label} fallback={server.name} />
          </div>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <span className="font-mono text-xs text-slate-500">{server.hostname}</span>
            <Badge tone="slate">{server.plan.name}</Badge>
            <Badge tone="slate">{server.osTemplate.name}</Badge>
            {server.isFree && <Badge tone="brand">free</Badge>}
            {/* Priced through `renewQuote` (lib/renewal-charge.ts), the same
                function the Renew now button and worker/billing.ts charge
                through. This badge used to read `plan.priceCents` + "/mo",
                which is a DIFFERENT number: on a game server it advertised the
                base VPS plan's $8.99 for a product sold at $4.99, and on an
                annual server it implied a monthly bill for a term that renews
                in one charge. */}
            {!server.isFree && (
              <Badge tone="slate">
                {fmtMoney(renewQuote.totalCents)} / {renewQuote.durationLabel}
              </Badge>
            )}
          </div>
        </div>
        {/* Start/stop controls are useless on an ERROR (failed-provision) server —
            there is no working VM to control — so they're hidden and replaced by
            the retry/support banner below. */}
        {server.status !== "SUSPENDED" && server.status !== "ERROR" && !transitional && (
          <div className="flex flex-wrap items-center gap-2">
            {server.status === "RUNNING" && <OpenTerminalButton servers={terminalServers} />}
            <ServerControls serverId={server.id} status={server.status} busy={busy} />
          </div>
        )}
      </div>

      {server.status === "SUSPENDED" && (
        <div className="card mb-6 border-red-500/30 text-sm text-red-300">
          This server has been suspended{server.suspendedNote ? `: ${server.suspendedNote}` : "."}{" "}
          Contact support if you believe this is a mistake.
        </div>
      )}

      {server.status === "ERROR" && (
        <ProvisionErrorBanner serverId={server.id} reason={server.provisionError} />
      )}

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          {server.status === "DELETING"
            ? "Your server is being deleted…"
            : "Your server is being set up — this usually takes under two minutes. The page refreshes automatically."}
        </div>
      )}

      <ServerTabs
        initialTab={tab}
        overview={overview}
        manage={isGameServer ? <GameManage serverId={server.id} /> : undefined}
        mods={isGameServer ? <GameMods serverId={server.id} /> : undefined}
        controlPanel={<ControlPanel serverId={server.id} running={server.status === "RUNNING"} />}
        metrics={<MetricsPanel serverId={server.id} />}
        console={consolePanel}
        files={filesPanel}
        snapshots={snapshotsTab}
        backups={backupsTab}
        networking={networking}
        resize={resize}
        activity={activity}
      />
    </div>
  );
}

"use client";

import { useState, type ReactNode } from "react";
import { GamePanelHeader } from "./GamePanelHeader";
import { GameOverview } from "./GameOverview";
import { GameConsole } from "./GameConsole";
import { ModStore } from "./ModStore";
import { GamePlayersHub } from "./GamePlayersHub";
import { GameWorlds } from "./GameWorlds";
import { GameCommandLibrary } from "./GameCommandLibrary";
import { GamePlayerHistory } from "./GamePlayerHistory";
import { GameSchedules } from "./GameSchedules";
import type { GameHeaderData, PanelTab } from "./types";

const TABS: { key: PanelTab; label: string; mc?: boolean }[] = [
  { key: "overview", label: "Overview" },
  { key: "console", label: "Console" },
  { key: "files", label: "Files" },
  { key: "mods", label: "Mods" },
  { key: "plugins", label: "Plugins" },
  { key: "backups", label: "Backups" },
  { key: "players", label: "Players" },
  { key: "worlds", label: "Worlds", mc: true },
  { key: "commands", label: "Commands", mc: true },
  { key: "history", label: "History", mc: true },
  { key: "schedules", label: "Schedules" },
  { key: "settings", label: "Settings" },
  { key: "activity", label: "Activity" },
];

export function GameServerPanel({
  serverId,
  gameFamily,
  header,
  filesPanel,
  backupsPanel,
  settingsPanel,
  activityPanel,
  initialTab,
}: {
  serverId: string;
  gameFamily: string;
  header: GameHeaderData;
  filesPanel: ReactNode;
  backupsPanel: ReactNode;
  settingsPanel: ReactNode;
  activityPanel: ReactNode;
  initialTab?: string;
}) {
  const isMc = gameFamily === "minecraft";
  const visibleTabs = TABS.filter((t) => !t.mc || isMc);
  const keys = visibleTabs.map((t) => t.key as string);
  const [tab, setTab] = useState<PanelTab>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? (initialTab.toLowerCase() as PanelTab) : "overview"
  );

  const go = (t: PanelTab) => {
    setTab(t);
    window.history.replaceState(null, "", `?tab=${t}`);
    if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <div className="space-y-6">
      <GamePanelHeader serverId={serverId} gameFamily={gameFamily} data={header} />

      <div className="sticky top-2 z-10 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/80 p-1 backdrop-blur-xl">
        {visibleTabs.map((t) => {
          const active = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => go(t.key)}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t.label}
            </button>
          );
        })}
      </div>

      <div className="animate-fade-up">
        {tab === "overview" && <GameOverview serverId={serverId} gameFamily={gameFamily} data={header} onNavigate={go} />}
        {tab === "console" && <GameConsole serverId={serverId} running={header.running} />}
        {tab === "files" && filesPanel}
        {tab === "mods" && <ModStore serverId={serverId} scope="mods" onOpenPlugins={() => go("plugins")} />}
        {tab === "plugins" && <ModStore serverId={serverId} scope="plugins" onOpenPlugins={() => go("mods")} />}
        {tab === "backups" && backupsPanel}
        {tab === "players" && <GamePlayersHub serverId={serverId} running={header.running} playersMax={header.players.max} isMc={isMc} />}
        {tab === "worlds" && isMc && <GameWorlds serverId={serverId} running={header.running} />}
        {tab === "commands" && isMc && <GameCommandLibrary serverId={serverId} running={header.running} />}
        {tab === "history" && isMc && <GamePlayerHistory serverId={serverId} />}
        {tab === "schedules" && <GameSchedules serverId={serverId} />}
        {tab === "settings" && settingsPanel}
        {tab === "activity" && activityPanel}
      </div>
    </div>
  );
}
