const REAL_APPLY_FAMILIES = new Set<string>(["palworld", "minecraft", "rust", "valheim"]);

function familyRealApplyEnabled(family: string): boolean {
  return REAL_APPLY_ENABLED || REAL_APPLY_FAMILIES.has(family);
}

const CONNECT_TIMEOUT_MS = 15_000;
const EXEC_TIMEOUT_MS = 30_000;

async function notify(userId: string, title: string, body?: string, href?: string) {
