/**
 * A plain module-level flag — not React state/context — tracking whether a
 * file is actively uploading anywhere on the current page. `AutoRefresh`
 * (components/AutoRefresh.tsx) can fire `router.refresh()` every few seconds
 * while a server has any job queued/running, completely unrelated to file
 * uploads; a large File Manager upload (well over 5s for anything sizeable)
 * was getting interrupted mid-transfer by that refresh.
 *
 * A module-level counter (not boolean) so two overlapping uploads — e.g. a
 * multi-file drop — don't have the first one finishing prematurely clear the
 * guard while the second is still in flight.
 *
 * Plain module state, not context, because AutoRefresh and whatever is
 * uploading can live in entirely unrelated parts of the component tree
 * (AutoRefresh is rendered from many different pages) — threading this
 * through props/context everywhere it would be needed is exactly the
 * over-engineering this fix doesn't need.
 */
let count = 0;

export function beginUpload(): void {
  count++;
}

export function endUpload(): void {
  count = Math.max(0, count - 1);
}

export function isUploadInProgress(): boolean {
  return count > 0;
}
