"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { familyFor } from "./game-config";

/**
 * Mod-manager actions.
 *
 * Customers browse the per-game mod/plugin CATALOG (GameMod) and one-click
 * install/uninstall onto their server. Each change writes the desired state to a
 * `ServerMod` row (INSTALLING / REMOVING) and enqueues a single GAME_MOD_SYNC job
 * that reconciles the server to that state — the same state-driven pattern as
 * GAME_CONFIG (worker reads the DB, no per-op payloads to trust).
 *
 * Ownership + the "one in-flight job per server" invariant mirror
 * lib/actions-game-config.ts.
 */

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true, gamePlan: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function hasInflightJob(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

export type CatalogMod = {
  id: string;
  name: string;
  slug: string;
  category: string;
  source: string;
  url: string | null;
  description: string | null;
  iconUrl: string | null;
  paid: boolean;
  featured: boolean;
  appliesToVariant: string | null;
  /** install state for THIS server: null = not installed. */
  status: string | null;
  error: string | null;
};

export type ModsView = {
  family: string;
  variant: string | null;
  /** catalog entries (compatible with the server's variant), grouped by category. */
  categories: { category: string; mods: CatalogMod[] }[];
  installedCount: number;
  busy: boolean;
};

/**
 * Load the mod catalog for an owned game server, annotated with each mod's
 * install state on this server. Only mods for the server's game family and
 * compatible with its selected variant are returned.
 */
export async function getServerMods(
  serverId: string
): Promise<{ error?: string; view?: ModsView }> {
  const { server } = await ownedServer(serverId);
  const family = familyFor(server);
  if (!family) return { error: "This server doesn't support mods." };

  const variant = server.gameVariant ?? null;

  const [catalog, installed, busy] = await Promise.all([
    db.gameMod.findMany({
      where: { gameFamily: family, active: true },
      orderBy: [{ featured: "desc" }, { popularity: "desc" }, { name: "asc" }],
    }),
    db.serverMod.findMany({ where: { serverId } }),
    hasInflightJob(serverId),
  ]);

  const stateByMod = new Map(installed.map((m) => [m.modId, m]));

  // Hide mods that target a different loader/variant than the server runs.
  const compatible = catalog.filter(
    (m) => !m.appliesToVariant || !variant || m.appliesToVariant === variant
  );

  const byCategory = new Map<string, CatalogMod[]>();
  for (const m of compatible) {
    const st = stateByMod.get(m.id);
    const row: CatalogMod = {
      id: m.id,
      name: m.name,
      slug: m.slug,
      category: m.category,
      source: m.source,
      url: m.url,
      description: m.description,
      iconUrl: m.iconUrl,
      paid: m.paid,
      featured: m.featured,
      appliesToVariant: m.appliesToVariant,
      status: st?.status ?? null,
      error: st?.error ?? null,
    };
    const arr = byCategory.get(m.category) ?? [];
    arr.push(row);
    byCategory.set(m.category, arr);
  }

  const categories = [...byCategory.entries()]
    .map(([category, mods]) => ({ category, mods }))
    .sort((a, b) => a.category.localeCompare(b.category));

  const installedCount = installed.filter(
    (m) => m.status === "INSTALLED" || m.status === "INSTALLING"
  ).length;

  return { view: { family, variant, categories, installedCount, busy } };
}

/** Queue a mod for install on an owned server. */
export async function installMod(
  serverId: string,
  modId: string
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);
  const family = familyFor(server);
  if (!family) return { error: "This server doesn't support mods." };

  const mod = await db.gameMod.findUnique({ where: { id: modId } });
  if (!mod || !mod.active) return { error: "That mod is unavailable." };
  if (mod.gameFamily !== family) return { error: "That mod isn't for this game." };
  if (mod.appliesToVariant && server.gameVariant && mod.appliesToVariant !== server.gameVariant) {
    return { error: `${mod.name} needs the "${mod.appliesToVariant}" server type.` };
  }

  const existing = await db.serverMod.findUnique({
    where: { serverId_modId: { serverId, modId } },
  });
  if (existing && (existing.status === "INSTALLED" || existing.status === "INSTALLING")) {
    return { error: `${mod.name} is already installed.` };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.serverMod.upsert({
    where: { serverId_modId: { serverId, modId } },
    create: { serverId, modId, status: "INSTALLING", error: null },
    update: { status: "INSTALLING", error: null },
  });
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "gameserver.mod.install", detail: `${serverId} mod=${mod.slug}` },
  });

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

/** Queue a mod for removal from an owned server. */
export async function uninstallMod(
  serverId: string,
  modId: string
): Promise<{ error?: string; ok?: boolean }> {
  const { user, server } = await ownedServer(serverId);

  const existing = await db.serverMod.findUnique({
    where: { serverId_modId: { serverId, modId } },
    include: { mod: true },
  });
  if (!existing || existing.status === "REMOVED") {
    return { error: "That mod isn't installed." };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.serverMod.update({
    where: { serverId_modId: { serverId, modId } },
    data: { status: "REMOVING", error: null },
  });
  await db.job.create({ data: { type: "GAME_MOD_SYNC", serverId } });
  await db.auditLog.create({
    data: { userId: user.id, action: "gameserver.mod.uninstall", detail: `${serverId} mod=${existing.mod.slug}` },
  });

  void server; // ownership already enforced above
  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}

"use client";

import { useCallback, useEffect, useMemo, useState, useTransition } from "react";
import { getServerMods, installMod, uninstallMod, type CatalogMod } from "@/lib/actions-mods";

/**
 * Mod Store — the panel's differentiator. An App-Store-style browse experience
 * over the per-game mod/plugin catalog (GameMod), with a detail view and a
 * version → confirm install flow.
 *
 * REAL backend: catalog + install state + install/uninstall come from
 * lib/actions-mods.ts (state-driven GAME_MOD_SYNC job). DERIVED/illustrative
 * (clearly labelled in the UI): star rating, install counts, screenshots,
 * version history, reviews and changelog — the GameMod model has no such fields
 * yet, so they are computed deterministically from the mod's slug so the
 * storefront feels alive. The version dropdown is display-only: the installer
 * always applies the latest compatible build (see the note in the install modal).
 *
 * `scope="plugins"` reframes the same catalog toward loader plugins (admin,
 * protection, economy, chat, permissions…), falling back to the full catalog
 * with a note when a family draws no plugin categories.
 */

const PLUGIN_KEYWORDS = ["admin", "permission", "protection", "economy", "chat", "discord", "core", "utility", "clan", "rank", "teleport"];

// ---- deterministic "storefront" meta (illustrative, derived from slug) ----
function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}
function ratingFor(m: CatalogMod): number {
  return 4 + ((hash(m.slug) % 11) / 10); // 4.0 – 5.0
}
function installsFor(m: CatalogMod): number {
  const base = 800 + (hash(m.slug) % 90000);
  return m.featured ? base * 4 + 120000 : base;
}
function fmtInstalls(n: number): string {
  if (n >= 1000) return `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k`;
  return String(n);
}
function versionsFor(m: CatalogMod): string[] {
  const h = hash(m.slug);
  const major = 1 + (h % 4);
  const minor = h % 12;
  return [`Latest (v${major}.${minor})`, `v${major}.${Math.max(0, minor - 1)}`, `v${major - 1 >= 1 ? major - 1 : 1}.9`];
}
function reviewsFor(m: CatalogMod): { author: string; stars: number; body: string }[] {
  const h = hash(m.slug);
  const authors = ["RustLegend", "AdminAce", "SurvivalKing", "ModHoarder", "PvPMaster"];
  return [
    { author: authors[h % authors.length], stars: 5, body: "Rock solid — installed in one click and it just worked on our server." },
    { author: authors[(h >> 3) % authors.length], stars: 4, body: "Great feature set. Slight config learning curve but well worth it." },
  ];
}

type SortKey = "popular" | "rating" | "name";

export function ModStore({
  serverId,
  scope,
  onOpenPlugins,
}: {
  serverId: string;
  scope: "mods" | "plugins";
  onOpenPlugins?: () => void;
}) {
  const [mods, setMods] = useState<CatalogMod[] | null>(null);
  const [variant, setVariant] = useState<string | null>(null);
  const [installedCount, setInstalledCount] = useState(0);
  const [busy, setBusy] = useState(false);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [actErr, setActErr] = useState<string | null>(null);

  const [view, setView] = useState<"browse" | "installed">("browse");
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("all");
  const [sort, setSort] = useState<SortKey>("popular");
  const [detail, setDetail] = useState<CatalogMod | null>(null);
  const [pending, start] = useTransition();

  const refresh = useCallback(async () => {
    const res = await getServerMods(serverId);
    if (res.error || !res.view) {
      setLoadErr(res.error ?? "Unavailable.");
      setMods(null);
      return;
    }
    const flat = res.view.categories.flatMap((c) => c.mods);
    setMods(flat);
    setVariant(res.view.variant);
    setInstalledCount(res.view.installedCount);
    setBusy(res.view.busy);
    setLoadErr(null);
  }, [serverId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Poll while a change is applying.
  const applying = busy || (mods?.some((m) => m.status === "INSTALLING" || m.status === "REMOVING") ?? false);
  useEffect(() => {
    if (!applying) return;
    const t = setInterval(() => void refresh(), 5000);
    return () => clearInterval(t);
  }, [applying, refresh]);

  const run = (fn: () => Promise<{ error?: string; ok?: boolean }>) => {
    setActErr(null);
    start(async () => {
      const r = await fn();
      if (r.error) setActErr(r.error);
      await refresh();
    });
  };

  const scoped = useMemo(() => {
    if (!mods) return [];
    if (scope !== "plugins") return mods;
    const hits = mods.filter((m) => PLUGIN_KEYWORDS.some((k) => m.category.toLowerCase().includes(k)));
    return hits.length ? hits : mods;
  }, [mods, scope]);

  const categories = useMemo(() => {
    const set = new Set(scoped.map((m) => m.category));
    return ["all", ...[...set].sort()];
  }, [scoped]);

