  }
}

/** Resolve a direct download URL from the source's API (worker-side). */
async function resolveUrl(mod: ModRowFull): Promise<string | null> {
  const id = mod.sourceId ?? "";
  try {
    switch (mod.source) {
      case "umod":
        return `https://umod.org/plugins/${id}.cs`;
      case "spigotmc":
        return `https://api.spiget.org/v2/resources/${id}/download`;
      case "modrinth": {
        const loader = modrinthLoader(mod);
        const q = loader ? `?loaders=["${loader}"]` : "";
        const res = await fetch(`https://api.modrinth.com/v2/project/${id}/version${q}`, {
          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
        });
        if (!res.ok) return null;
        const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
        const v = versions[0];
        if (!v) return null;
        return (v.files.find((f) => f.primary) ?? v.files[0])?.url ?? null;
      }
      case "thunderstore": {
        const [author, ...rest] = id.split("-");
        if (!rest.length) return null;
        const res = await fetch(`https://thunderstore.io/api/experimental/package/${author}/${rest.join("-")}/`, {
          headers: { "User-Agent": "Nxeon/1.0 (mod-manager)" },
        });
        if (!res.ok) return null;
        const pkg = (await res.json()) as { latest?: { download_url?: string } };
        return pkg.latest?.download_url ?? null;
      }
      default:
        return null;
    }
  } catch (e) {
    console.error(`[game-mods] resolveUrl(${mod.source}/${id}) failed`, e);
    return null;
  }
}

function modrinthLoader(mod: ModRowFull): string | null {
  // Prefer the mod's own loader target; fall back to the server's variant.
  const key = mod.appliesTo ?? mod.variant ?? "";
  const map: Record<string, string> = {
    paper: "paper", spigot: "spigot", purpur: "purpur", bukkit: "bukkit",
    fabric: "fabric", forge: "forge", neoforge: "neoforge", quilt: "quilt",
  };
  return map[key] ?? null;
}

/** Shell snippet that echoes (creating if needed) the mod/plugin dir for family+variant. */
function modDirShell(family: string, variant: string | null): string | null {
  switch (family) {
    case "minecraft": {
      const modded = variant && ["fabric", "forge", "neoforge", "quilt"].includes(variant);
      const sub = modded ? "mods" : "plugins";
      return `root=$(find /opt /srv /home /root -maxdepth 6 -name server.properties -printf '%h\\n' 2>/dev/null | head -1); [ -n "$root" ] && { mkdir -p "$root/${sub}"; echo "$root/${sub}"; }`;
    }
    case "rust":
      return `d=$(find /opt /srv /home -maxdepth 9 -type d \\( -name oxide -o -name carbon \\) 2>/dev/null | head -1); [ -n "$d" ] && { mkdir -p "$d/plugins"; echo "$d/plugins"; }`;
    // Was a case-sensitive `find -name BepInEx` — always a no-op even with
    // BepInEx installed, since lloesche/valheim-server's own real directory is
    // lowercase `bepinex` (confirmed against its README). Use the documented,
    // fixed path directly instead of searching for it: `/config` is the
    // catalog's own `-v /opt/valheim/config:/config` mount, and the image
    // itself watches `/config/bepinex/plugins` for user-added plugins and
    // copies them into the real BepInEx plugin dir on boot — this is the
    // customer-facing "drop mods here" folder by design, not an internal path.
    case "valheim":
      return `d=/opt/valheim/config/bepinex/plugins; [ -d /opt/valheim/config/bepinex ] && { mkdir -p "$d"; echo "$d"; }`;
    default:
      return null;
  }
}

