import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { vmRrd, nodeRrd, pveFor, pveForNode } from "@/lib/proxmox";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  const timeframe = ["hour", "day", "week", "month"].includes(req.nextUrl.searchParams.get("tf") ?? "")
    ? req.nextUrl.searchParams.get("tf")!
    : "hour";

  const serverId = req.nextUrl.searchParams.get("serverId");
  try {
    if (serverId) {
      const server = await db.server.findUnique({ where: { id: serverId }, include: { node: true } });
      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
        return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
      }
      // Query the node the VM actually lives on — vmids collide across nodes, so
      // defaulting to the primary would leak another tenant's same-numbered VM.
      const conn = server.node
        ? pveFor({
            apiUrl: server.node.apiUrl,
            pveNode: server.node.pveNode,
            tokenId: server.node.tokenId,
            tokenSecret: server.node.tokenSecret,
          })
        : undefined;
      const data = await vmRrd(server.vmid, timeframe, conn);
      return NextResponse.json({ data }, { headers: NO_STORE_HEADERS });
    }
    if (user.role !== "ADMIN") {
      return NextResponse.json({ error: "forbidden" }, { status: 403, headers: NO_STORE_HEADERS });
    }
    // Fleet-wide admin chart — was hardcoded to the primary node's env-derived
    // connection, which silently omitted every other node. Now selectable via
    // ?node=<id>, defaulting to the primary (or first enabled) node.
    const nodes = await db.node.findMany({
      where: { enabled: true },
      orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
    });
    const nodeParam = req.nextUrl.searchParams.get("node");
    const target = (nodeParam && nodes.find((n) => n.id === nodeParam)) || nodes[0];
    const conn = target ? pveForNode(target) : undefined;
    const data = await nodeRrd(timeframe, conn);
    return NextResponse.json(
      { data, nodes: nodes.map((n) => ({ id: n.id, name: n.name })), nodeId: target?.id ?? null },
      { headers: NO_STORE_HEADERS }
    );
  } catch {
    // An empty series is the SAME shape we return for a VM that genuinely has
    // no RRD data yet, so swallowing the error here told the customer "your
    // server reported nothing" when the truth was "we could not reach Proxmox
    // to ask". Keep the 200 + empty array (the chart handles it), but state
    // plainly that this is an unavailable upstream, not an observed silence.
    return NextResponse.json(
      { data: [], unavailable: true },
      { headers: NO_STORE_HEADERS },
    );
  }
}

