export async function sendGameCommand(
  serverId: string,
  command: string
): Promise<{ ok: true; response: string } | { ok: false; error: string }> {
  try {
    const { user, server } = await ownedServer(serverId);
    const spec = requireSpec(server);
    if (spec.rcon !== "source")
      return { ok: false, error: `Remote console commands are not available for ${spec.label}.` };
    const valid = validateRconCommand(command);
    if (!valid.ok) return { ok: false, error: valid.error };
    const limited = throttle(user.id, "rcon", 30);
    if (limited) return { ok: false, error: limited };

    if (SANDBOX) return { ok: true, response: `(sandbox) ran: ${valid.command}` };
    if (server.status !== "RUNNING")
      return { ok: false, error: "The server must be running to send console commands." };

    await db.auditLog.create({
      data: { userId: user.id, action: "gameserver.rcon", detail: `${spec.family}: ${valid.command.slice(0, 120)}` },
    });
    const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, valid.command));
    return res.ok ? { ok: true, response: res.response } : { ok: false, error: res.error };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/**
 * Broadcasts a chat message to everyone on the server, branded with the
 * server's own name instead of the connection it was sent over.
 *
 * Deliberately uses `tellraw`, not `say` — Minecraft's remote-console RCON
 * connection identifies itself as a sender named "Rcon", so `/say <msg>` (which
 * prefixes the broadcast with the ISSUING sender's name) shows up in chat as
 * "[Rcon] <msg>" instead of a real server identity. `tellraw` fully controls
 * the displayed text, sidestepping the sender-name entirely.
 */
export async function broadcastToGameServer(serverId: string, message: string): Promise<Result> {
  try {
    const { server } = await ownedServer(serverId);
    const clean = message.trim();
    if (!clean) return { ok: false, error: "Enter a message to broadcast." };
    if (clean.length > 250) return { ok: false, error: "Message is too long (max 250 characters)." };
    const senderName = server.label || server.hostname;
    const payload = JSON.stringify([
      { text: `[${senderName}] `, color: "gold", bold: true },
      { text: clean, color: "white" },
    ]);
    const r = await mcRcon(serverId, `tellraw @a ${payload}`, "gameserver.broadcast", clean);
    return r.ok ? { ok: true } : r;
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

