const MC_PLAYER_RE = /^[A-Za-z0-9_]{3,16}$/;

function validMcName(name: string): { ok: true; name: string } | { ok: false; error: string } {
  const trimmed = name.trim();
  if (!MC_PLAYER_RE.test(trimmed)) return { ok: false, error: "Invalid Minecraft username (3-16 chars, letters/digits/underscore)." };
  return { ok: true, name: trimmed };
}

function stripAnsi(s: string): string {
  return s.replace(/\x1b\[[0-9;]*m/g, "");
}

async function mcRcon(serverId: string, command: string, auditAction: string, auditDetail: string): Promise<{ ok: true; response: string } | { ok: false; error: string }> {
  const { user, server } = await ownedServer(serverId);
  const spec = requireSpec(server);
  if (spec.family !== "minecraft") return { ok: false, error: "This feature is only available for Minecraft servers." };
  if (spec.rcon !== "source") return { ok: false, error: "RCON is not available for this server." };
  const limited = throttle(user.id, "mc-mgmt", 30);
  if (limited) return { ok: false, error: limited };
  if (SANDBOX) return { ok: true, response: `(sandbox) ${command}` };
  if (server.status !== "RUNNING") return { ok: false, error: "The server must be running." };
  await db.auditLog.create({ data: { userId: user.id, action: auditAction, detail: auditDetail } });
  const res = await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, command));
  return res.ok ? { ok: true, response: stripAnsi(res.response) } : { ok: false, error: res.error };
}

export type RconProtocol =
  | "source" // Valve Source RCON (Minecraft, CS2, Palworld) — implemented here
  | "rust-web" // Rust WebSocket RCON — different protocol, deferred
  | "none"; // no remote console protocol (Valheim/Terraria vanilla)

/** Where a family stores the RCON credentials, and how to parse that file. */
type RconConfig = {
  /** Config-file path candidates to try first (absolute). */
  candidates: string[];
  /** Roots to bounded-`find` under if none of the candidates exist. */
  findRoots: string[];
  /** File name to find. */
  findName: string;
  /** File format. */
  kind: "properties" | "palworld-ini";
  /** Key that gates RCON being on (value compared case-insensitively to true/1). */
  enableKey?: string;
  /** Key holding the RCON password. */
  passwordKey: string;
  /** Key holding the RCON port (falls back to `defaultPort`). */
  portKey?: string;
  /** Port used when the file does not specify one. */
  defaultPort: number;
};

export type GameControlSpec = {
  family: GameFamily;
  label: string;
  /** systemd unit-name hints (first that resolves wins). Compile-time constants. */
