/** Compute the next run for an interval-based schedule. */
function computeNextInterval(intervalMinutes: number, from: Date = new Date()): Date {
  return new Date(from.getTime() + intervalMinutes * 60_000);
}

function validTime(hour: number, minute: number): boolean {
  return Number.isInteger(hour) && hour >= 0 && hour <= 23 && Number.isInteger(minute) && minute >= 0 && minute <= 59;
}

/** Cap on schedules per server (a daily restart or three is the realistic case). */
const MAX_SCHEDULES = 8;

