 * command over the private network, so the VM must be running.
 */
export async function triggerGameUpdate(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);
  if (!isGameServer(server)) return { error: "Updates are only available for game servers." };
  if (server.status !== "RUNNING") {
    return { error: "Server must be running to apply a game update." };
  }
  if (!server.ipAddress || !serverRootPassword(server)) {
    return { error: "Server is still provisioning — try again shortly." };
